use super::*;use crate::{Value,json};
fn input(name:&str)->Option<Vec<Value>>{Some(std::fs::read_to_string(std::env::var_os(name)?).unwrap().lines().map(|s|serde_json::from_str(s).unwrap()).collect())}
fn n(r:&Value,k:&str)->i64{r[k].as_i64().unwrap()}
fn fold(h:&mut u32,values:impl IntoIterator<Item=i64>){for v in values{*h=(*h^v as u32).wrapping_mul(16777619);}}
fn hex(s:&str)->Vec<u8>{(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()}
#[test]fn late_build_audio_matches448_actual_coupled_readers_and8_empty8_reset_prefixes(){
 let Some(rows)=input("NATIVE_LATE_BUILD_AUDIO_TRACE")else{return;};let(mut h,mut count)=(2166136261,0);
 for r in rows{let mut state=State::default();match r["kind"].as_str().unwrap(){"mainSource"=>continue,"empty"=>{state.late_build_clock=n(&r,"before")as u32;state.end_late_build_reader();assert_eq!(i64::from(state.late_build_clock),n(&r,"after"));fold(&mut h,[n(&r,"before"),n(&r,"after")]);},"mission"=>{let before=hex(r["before"].as_str().unwrap());let mut out=before.clone();state.late_build_clock=u32::from_le_bytes(before[8..12].try_into().unwrap());state.reset_late_build_mission();out[8..12].copy_from_slice(&state.late_build_clock.to_le_bytes());assert_eq!(out,hex(r["after"].as_str().unwrap()));fold(&mut h,before.into_iter().chain(out).map(i64::from));},"reader"=>{
  count+=1;let bank=n(&r,"bank")as usize;let index=|id|crate::original_audio::BANKS[bank].iter().position(|d|d.id==id).unwrap();let(i44,i46)=(index(44),index(46));for(id,i)in[(44,i44),(46,i46)]{assert_eq!(i64::from(crate::original_audio::BANKS[bank][i].minimum),n(&r,&format!("min{id}")));state.last[bank][i]=n(&r,&format!("last{id}Before"))as i16;}state.late_build_clock=n(&r,"timerBefore")as u32;state.effect_counter=n(&r,"counterBefore")as i16;let high=n(&r,"counterBefore")as u32&0xffff0000;let full=|s:&State|i64::from(high|u32::from(s.effect_counter as u16));let camera:[i16;2]=std::array::from_fn(|i|r["camera"][i].as_i64().unwrap()as i16);let mut mixes=Vec::<Vec<i64>>::new();let mut pending=None;
  for stage in r["stages"].as_array().unwrap(){let v=stage.as_array().unwrap().iter().map(|v|v.as_i64().unwrap()).collect::<Vec<_>>();let pc=v[0]as u32;fold(&mut h,v.iter().copied());if[0x40ebd7,0x40ed9f,0x40ef94].contains(&pc){assert!(pending.is_none());assert_eq!((i64::from(state.late_build_clock),full(&state)),(v[4],v[5]));let kind=if pc==0x40ebd7{Stage::Frame7}else if pc==0x40ed9f{Stage::BuildComplete}else{Stage::BridgeComplete};let before=state.late_build_clock;let counter=full(&state);let point=[v[2]as i16,v[3]as i16];let eligible=!crate::original_feedback::outside_view(point,camera,[320,240])&&(kind!=Stage::Frame7||before==0);let result=state.late_build_opportunity(kind,point,camera,[320,240],bank,n(&r,"clock")as i16,n(&r,"master")!=0);if let Some(d)=result{mixes.push(vec![i64::from(d.id),i64::from(if kind==Stage::BridgeComplete{100}else{before}),counter]);}if eligible{pending=Some((if kind==Stage::Frame7{0x40ed52}else if kind==Stage::BuildComplete{0x40ee72}else{0x40efea},i64::from(before),if kind==Stage::BridgeComplete{counter}else{full(&state)}));}}
   else if[0x40ed52,0x40ee72,0x40efea].contains(&pc){assert_eq!(pending.take(),Some((pc,v[4],v[5])));}
   else{assert_eq!(pc,0x40f161);assert!(pending.is_none());assert_eq!((i64::from(state.late_build_clock),full(&state)),(v[4],v[5]));state.end_late_build_reader();}}
  assert_eq!(mixes,serde_json::from_value::<Vec<Vec<i64>>>(r["mixes"].clone()).unwrap(),"case{}/{}",n(&r,"scenario"),n(&r,"tick"));assert_eq!((i64::from(state.late_build_clock),full(&state),i64::from(state.last[bank][i44]),i64::from(state.last[bank][i46])),(n(&r,"timer"),n(&r,"counter"),n(&r,"last44"),n(&r,"last46")));fold(&mut h,[n(&r,"scenario"),n(&r,"tick"),n(&r,"timer"),n(&r,"counter"),n(&r,"last44"),n(&r,"last46"),mixes.len()as i64]);fold(&mut h,mixes.into_iter().flatten());fold(&mut h,r["world"].as_array().unwrap().iter().map(|v|v.as_i64().unwrap()));
 },_=>panic!("unknown source record")}}
 assert_eq!((count,h),(448,3519120291));println!("LATE_AUDIO448_STATE signature={h}");
}
#[test]fn late_build_audio_actual_empty_game_reader_matches12_native_main_skip_windows(){let Some(rows)=input("NATIVE_LATE_BUILD_AUDIO_MAIN")else{return;};assert_eq!(rows.len(),12);for r in rows{let mut g=Game::new(0,1,49);g.map.original=true;g.import_native_world(&Value::Null);g.native_audio.late_build_clock=n(&r,"before")as u32;g.native_feedback.ui_clock=32767;g.native_audio.effect_counter=3;let rng=g.original_rng.words;g.update_native_building_trails(n(&r,"sceneResult")as u8);assert_eq!(i64::from(g.native_audio.late_build_clock),n(&r,"after"));assert_eq!((g.native_feedback.ui_clock,g.native_audio.effect_counter,g.original_rng.words),(32767,3,rng));assert!(g.events.is_empty());}}
#[test]fn late_build_audio_completion_and_main_gate_are_independent_and_clock_is_u32(){let mut s=State::default();s.opportunity_gate=255;s.explosion_cycle=7;s.late_build_clock=u32::MAX;assert!(s.late_build_opportunity(Stage::Frame7,[0,0],[0,0],[320,240],0,500,true).is_none());assert_eq!(s.late_build_opportunity(Stage::BuildComplete,[0,0],[0,0],[320,240],0,500,true).unwrap().id,46);assert_eq!((s.late_build_clock,s.opportunity_gate,s.explosion_cycle),(100,255,7));assert!(s.late_build_opportunity(Stage::BridgeComplete,[0,0],[0,0],[320,240],0,500,true).is_none());s.end_late_build_reader();assert_eq!((s.late_build_clock,s.effect_counter),(99,1));s.late_build_clock=0x80000000;s.end_late_build_reader();assert_eq!(s.late_build_clock,0x7fffffff);}
#[test]fn late_build_audio_muted_and_unavailable_view_contract_preserves_one_authoritative_timer(){let mut g=Game::new(0,1,49);g.map.original=true;g.multiplayer=true;g.native_feedback.ui_clock=500;g.set_native_listener_settings(&json!({"0":{"soundEnabled":false,"view":{"camera":[0,0],"size":[320,240]},"hardwareContext":"1:0"},"1":{"soundEnabled":true}}));g.native_listener_audio.guest_audio.late_build_clock=7;g.emit_native_late_build_audio(Stage::Frame7,[100,100]);assert_eq!((g.native_audio.late_build_clock,g.native_listener_audio.guest_audio.late_build_clock),(100,7));assert!(g.events.is_empty());g.finish_native_late_build_audio_reader();assert_eq!((g.native_audio.late_build_clock,g.native_listener_audio.guest_audio.late_build_clock),(99,6));let before=(g.native_audio.late_build_clock,g.native_listener_audio.guest_audio.late_build_clock);for _ in 0..12{g.step_native_ui_only(1./17.);}assert_eq!((g.native_audio.late_build_clock,g.native_listener_audio.guest_audio.late_build_clock),before);}
